 * The in-memory document tree that a configuration document parses into,
 * plus the path bookkeeping shared by error messages and the `keys` output.
 */

export function makeTable() {
  return { kind: 'table', map: new Map(), headerOpened: false }
}

export function makeArrayOfTables() {
  return { kind: 'aot', items: [] }
}

export function makeArray(items) {
  return { kind: 'array', items }
}

export function makeScalar(kind, value) {
  return { kind, value }
}

/**
 * Renders a path (an array of string key segments and `{ index }` array
 * segments) the way both error messages and `keys` output display it: keys
 * joined by `.`, indices appended as `[i]`.
 */
export function pathToString(path) {
  let out = ''
  for (const segment of path) {
    if (typeof segment === 'object') {
      out += '[' + segment.index + ']'
    } else {
      out += out ? '.' + segment : segment
    }
  }
  return out
}
"}

