{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-r9HHhZ/src/line-parser.js","content":"/**
 * A cursor over one line of source text, plus the low-level grammar pieces
 * (names, strings, values) that both key/value lines and table headers are
 * built from.
 */

import { ParseError } from './errors.js'
import { makeTable, makeArray, makeScalar } from './model.js'

const BARE_NAME = /[A-Za-z0-9_-]/

export class LineParser {
  constructor(line, lineNumber) {
    this.s = line
    this.i = 0
    this.n = line.length
    this.lineNumber = lineNumber
  }

  eof() {
    return this.i >= this.n
  }

  peek() {
    return this.s[this.i]
  }

  err(reason) {
    throw new ParseError(this.lineNumber, reason)
  }

  /** Skips spaces and tabs only; other whitespace never appears mid-line. */
  skipSpaces() {
    while (!this.eof() && (this.peek() === ' ' || this.peek() === '\t')) this.i++
  }

  /**
   * Skips spaces and tabs, then, if a `#` or `;` follows, treats the rest of
   * the line as a comment by jumping to the end. Used at every boundary
   * between tokens, where a comment marker always ends the line outright.
   */
  skipBoundary() {
    this.skipSpaces()
    if (!this.eof() && (this.peek() === '#' || this.peek() === ';')) this.i = this.n
  }
}

function parseBasicString(p) {
  p.i++ // consume opening quote
  let out = ''
  for (;;) {
    if (p.eof()) p.err('unterminated string')
    const c = p.s[p.i++]
    if (c === '"') return out
    if (c === '\\') {
      if (p.eof()) p.err('unterminated string')
      const e = p.s[p.i++]
      switch (e) {
        case '"': out += '"'; break
        case '\\': out += '\\'; break
        case 'n': out += '\n'; break
        case 't': out += '\t'; break
        case 'r': out += '\r'; break
        case '0': out += '\0'; break
        case 'u': {
          const hex = p.s.slice(p.i, p.i + 4)
          if (!/^[0-9A-Fa-f]{4}$/.test(hex)) p.err('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          p.i += 4
          break
        }
        default:
          p.err('invalid escape \\' + (e === undefined ? '' : e))
      }
    } else {
      out += c
    }
  }
}

function parseLiteralString(p) {
  p.i++ // consume opening quote
  const start = p.i
  for (;;) {
    if (p.eof()) p.err('unterminated string')
    const c = p.s[p.i++]
    if (c === "'") return p.s.slice(start, p.i - 1)
  }
}

/** Parses one bare-word or quoted-string name; assumes leading spaces are gone. */
function parseName(p) {
  if (p.eof()) p.err('expected a name')
  const c = p.peek()
  if (c === '"') return parseBasicString(p)
  if (c === "'") return parseLiteralString(p)
  if (BARE_NAME.test(c)) {
    const start = p.i
    while (!p.eof() && BARE_NAME.test(p.peek())) p.i++
    return p.s.slice(start, p.i)
  }
  p.err('expected a name')
}

/** Parses a dotted name, returning its parts. Spaces/tabs may surround each dot. */
export function parseDottedName(p) {
  const parts = [parseName(p)]
  for (;;) {
    p.skipSpaces()
    if (!p.eof() && p.peek() === '.') {
      p.i++
      p.skipSpaces()
      parts.push(parseName(p))
    } else {
      break
    }
  }
  return parts
}

const INTEGER_RE = /^[+-]?\d+(_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

function parseBareValue(word, p) {
  if (word === 'true') return makeScalar('boolean', true)
  if (word === 'false') return makeScalar('boolean', false)
  if (INTEGER_RE.test(word)) return makeScalar('integer', Number(word.replace(/_/g, '')))
  if (FLOAT_RE.test(word) && /[.eE]/.test(word)) {
    return makeScalar('float', Number(word.replace(/_/g, '')))
  }
  p.err('invalid value ' + word)
}

/**
 * Parses one value at the current position. `path` is the document path
 * this value will be assigned to, threaded through only so that inline
 * tables nested inside it can report accurate error paths.
 */
export function parseValue(p, path) {
  p.skipBoundary()
  if (p.eof()) p.err('expected a value')
  const c = p.peek()
  if (c === ',' || c === ']' || c === '}') p.err('expected a value')
  if (c === '"') return makeScalar('string', parseBasicString(p))
  if (c === "'") return makeScalar('string', parseLiteralString(p))
  if (c === '[') return parseArrayValue(p, path)
  if (c === '{') return parseInlineTable(p, path)

  const start = p.i
  while (!p.eof()) {
    const ch = p.peek()
    if (ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}') break
    p.i++
  }
  return parseBareValue(p.s.slice(start, p.i), p)
}

function parseArrayValue(p, path) {
  p.i++ // consume '['
  const items = []
  p.skipBoundary()
  if (!p.eof() && p.peek() === ']') {
    p.i++
    return makeArray(items)
  }
  for (;;) {
    if (p.eof()) p.err('unterminated array')
    items.push(parseValue(p, path.concat([{ index: items.length }])))
    p.skipBoundary()
    if (p.eof()) p.err('unterminated array')
    if (p.peek() === ',') {
      p.i++
      p.skipBoundary()
      if (!p.eof() && p.peek() === ']') {
        p.i++
        return makeArray(items)
      }
      continue
    }
    if (p.peek() === ']') {
      p.i++
      return makeArray(items)
    }
    p.err('unterminated array')
  }
}

/** Walks or creates the table at `name` inside `node`, extending `path` as it goes. */
function walkIntoTable(node, name, path, p) {
  path.push(name)
  const child = node.map.get(name)
  if (child === undefined) {
    const t = makeTable()
    node.map.set(name, t)
    return t
  }
  if (child.kind === 'table') return child
  if (child.kind === 'aot') {
    path.push({ index: child.items.length - 1 })
    return child.items[child.items.length - 1]
  }
  p.err(pathToStringLocal(path) + ' is not a table')
}

function pathToStringLocal(path) {
  let out = ''
  for (const segment of path) {
    if (typeof segment === 'object') out += '[' + segment.index + ']'
    else out += out ? '.' + segment : segment
  }
  return out
}

/** Assigns `value` at `parts` inside `container`, whose own path is `basePath`. */
export function assignDotted(container, parts, value, basePath, p) {
  let node = container
  const path = basePath.slice()
  for (let idx = 0; idx < parts.length - 1; idx++) {
    node = walkIntoTable(node, parts[idx], path, p)
  }
  const lastName = parts[parts.length - 1]
  path.push(lastName)
  if (node.map.has(lastName)) {
    p.err('key ' + pathToStringLocal(path) + ' is defined twice')
  }
  node.map.set(lastName, value)
}

function parseInlineTable(p, path) {
  p.i++ // consume '{'
  const table = makeTable()
  p.skipBoundary()
  if (!p.eof() && p.peek() === '}') {
    p.i++
    return table
  }
  for (;;) {
    if (p.eof()) p.err('unterminated inline table')
    const parts = parseDottedName(p)
    p.skipBoundary()
    if (p.eof() || p.peek() !== '=') p.err('expected = in an inline table')
    p.i++
    const value = parseValue(p, path.concat(parts))
    assignDotted(table, parts, value, path, p)
    p.skipBoundary()
    if (p.eof()) p.err('unterminated inline table')
    if (p.peek() === ',') {
      p.i++
      p.skipBoundary()
      continue
    }
    if (p.peek() === '}') {
      p.i++
      return table
    }
    p.err('unterminated inline table')
  }
}
"}

