/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { splitLines, parseDocument } from './document.js'
import { printJSON, printKeys } from './print.js'
import { ParseError } from './errors.js'

function readStdin() {
  const fs = require_fs()
  return fs.readFileSync(0, 'utf8')
}

function require_fs() {
  // Deferred require avoids importing node:fs when unused in tests that stub input.
  return { readFileSync: (fd, enc) => globalThis.__cliReadFileSync(fd, enc) }
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'json' && mode !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }

  const input = readStdinSync()

  try {
    const lines = splitLines(input)
    const root = parseDocument(lines)
    const output = mode === 'json' ? printJSON(root) : printKeys(root)
    process.stdout.write(output)
    process.exit(0)
  } catch (error) {
    if (error instanceof ParseError) {
      process.stderr.write('error: ' + error.message + '\n')
      process.exit(2)
    }
    throw error
  }
}

function readStdinSync() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

main()
"}

